    var agg = TagMonoid(tag_word & 1u, (tag_word >> 1u) & 1u, (tag_word >> 2u) & 1u, (tag_word >> 3u) & 1u, (tag_word >> 4u) & 1u);
    sh_scratch[local_id.x] = agg;
    for (var i = 0u; i < firstTrailingBit(WG_SIZE); i += 1u) {
        workgroupBarrier();
        if local_id.x + (1u << i) < WG_SIZE {
